static const float length_breaks[3] = {0.160002798f, 0.379821658f, 0.389576942f};
static const float centers[2] = {0.269912243f, 0.384699315f};
static const float inv_scales[2] = {9.09840012f, 205.016968f};

int lqr_get_k(float LL, float LR, float K[4][10]) {
    if (!isfinite(LL) || !isfinite(LR) ||
        LL < LQR_LENGTH_MIN || LL > LQR_LENGTH_MAX ||
        LR < LQR_LENGTH_MIN || LR > LQR_LENGTH_MAX)
        return -1;

    int il = 0, ir = 0;
    while (il < LQR_SEGMENT_COUNT - 1 && LL >= length_breaks[il + 1]) ++il;
    while (ir < LQR_SEGMENT_COUNT - 1 && LR >= length_breaks[ir + 1]) ++ir;
    float x = (LL - centers[il]) * inv_scales[il];
    float y = (LR - centers[ir]) * inv_scales[ir];
    float xp[6] = {1.0f};
    float yp[6] = {1.0f};
    for (int i = 1; i <= 5; ++i) {
        xp[i] = xp[i - 1] * x;
        yp[i] = yp[i - 1] * y;
    }
    float features[21] = {xp[0] * yp[0], xp[1] * yp[0], xp[0] * yp[1], xp[2] * yp[0], xp[1] * yp[1], xp[0] * yp[2], xp[3] * yp[0], xp[2] * yp[1], xp[1] * yp[2], xp[0] * yp[3], xp[4] * yp[0], xp[3] * yp[1], xp[2] * yp[2], xp[1] * yp[3], xp[0] * yp[4], xp[5] * yp[0], xp[4] * yp[1], xp[3] * yp[2], xp[2] * yp[3], xp[1] * yp[4], xp[0] * yp[5]};
    for (int row = 0; row < 4; ++row) {
        for (int col = 0; col < 10; ++col) {
            float value = 0.0f;
            for (int k = 0; k < 21; ++k)
                value += K_coeffs[il][ir][row][col][k] * features[k];
            K[row][col] = value;
        }
    }
    return 0;
}

void lqr_compute_u(const float K[4][10], const float expect_state[10],
                   const float real_state[10], float U[4]) {
    for (int row = 0; row < 4; ++row) {
        U[row] = 0.0f;
        for (int col = 0; col < 10; ++col)
            U[row] += K[row][col] * (expect_state[col] - real_state[col]);
    }
}
